impl ScoutEngine {
    pub fn new(model: Arc<dyn ModelBackend>, tools: RepoTools, budget: ExplorerBudget) -> Self {
        let tools = tools
            .with_concurrency(budget.concurrency)
            .with_timeout(budget.tool_timeout());
        Self {
            model,
            tools,
            budget,
        }
    }

    pub fn tools(&self) -> &RepoTools {
